// TH16 v1.00a st01 MainFront:1053-1054 -> MainSub01b (async) + MainSub01 (sync).
// Source enmCreate coords are parent-FINAL relative; the creating caller is the stage
// script at (0,0), and control below also sits at (0,0), so child coords are unchanged.
// Omitted per transcription-policy: dropSeason/drop*/anm* (drops, presentation) and the
// birth ANIM + SPEEDUP EX records on every bullet (planned birth-animation omission).

const TIME_LIMIT: int = 2324;
const OPENING_BUFFER: int = 120;

// th16 bullet types (touhou-bullets.ecl aliases of the shared 0-43 slots)
const TH16_BALL: int = 416;        // source etSprite type 4
const TH16_RING_BALL: int = 448;   // source etSprite type 6
const BULLET_COLOR: int = 6;       // source etSprite color 6

// ---------------------------------------------------------------------------
// GirlBlueA01:448-455 / GirlRedA01:945-952 -> GirlA01:59-85
// ---------------------------------------------------------------------------
async sub girl_a() {
    set_invuln(65535);
    set_hurtbox(12fx);   // setHurtbox(24,24)
    set_hitbox(8fx);     // setHitbox(16,16)
    // moveVel(pi/2 + RANDF2*0.34906584, 1.0); RANDF2 in [-1,1], 20deg = 3641 BAM
    var r: int = rand(65536) - 32768;
    var off: int = r * 3641 / 32768;
    move_vel(0, (16384 + off) as angle, 1fx, EASE_LINEAR);
    wait(30);
    // moveVelTime(120, 0, -999999, [-1.0f]): mode0 keeps the angle, speed target 3(E)/4(NHL)
    var target: fx = 4fx;
    if global(GVAR_RANK) == RANK_EASY { target = 3fx; }
    move_speed(120, target, EASE_LINEAR);
    // !HL @GirlA01_at(); the value pushed for moveVelTime (4) is also the callee's wait([-1])
    if global(GVAR_RANK) >= RANK_HARD {
        var spd: fx = 4fx;
        var shots: int = 5;
        var gap: int = 12;
        if global(GVAR_RANK) == RANK_HARD { spd = 3fx; shots = 2; gap = 20; }
        girl_a_at(4, spd, shots, gap);
    }
    loop { wait(1); }
}

// GirlA01_at:87-133 (single aimed ball of type 4)
sub girl_a_at(delay: int, spd: fx, shots: int, gap: int) {
    wait(delay);                       // wait([-1]) at the call site
    sh_reset(0);                       // etNew(0)
    sh_sprite(0, TH16_BALL, BULLET_COLOR);   // etSprite(0, 4, 6)
    sh_ring(0, 0);
    sh_aim(0, 1);                      // etAim(0, 0): aimed fan
    sh_angle(0, 0deg, 3deg);           // etAngle(0, 0.0f, 0.05235988f)
    sh_count(0, 1, 1);                 // etCount(0, 1, 1)
    sh_speed(0, spd, 0fx);             // etSpeed(0, s0, 1.0f), M=1 uses s0
    for i in 0..shots {                // diffI($A, 1, 1, 2, 5)
        sh_fire(0);                    // etOn(0)
        wait(gap);                     // wait([-1]): 30/30/20/12
    }
}

// ---------------------------------------------------------------------------
// GirlB01:337-363
// ---------------------------------------------------------------------------
async sub girl_b() {
    set_invuln(65535);
    set_hurtbox(16fx);   // setHurtbox(32,32)
    set_hitbox(12fx);    // setHitbox(24,24)
    move_vel(0, 90deg, 4.3fx, EASE_LINEAR);   // moveVel(pi/2, 4.3)
    move_speed(80, 0fx, EASE_QUAD_OUT);       // moveVelTime(80, 4, -999999, 0.0)
    if global(GVAR_RANK) != RANK_EASY {       // !NHL @GirlB01_at() async
        spawn girl_b_at();
    }
    wait(80);
    move_vel(0, aim_player(), 0fx, EASE_LINEAR);   // moveVel(ANGLE_PLAYER, 0.0)
    move_speed(80, 1fx, EASE_QUAD_IN);             // moveVelTime(80, 1, -999999, 1.0)
    wait(60);
    loop { wait(1); }                              // source never returns
}

// GirlB01_at:365-394 (aimed fan of type 6)
async sub girl_b_at() {
    wait(120);
    var ways: int = 1;                 // etCountD(0, 1,1,3,3, 1,1,1,1)
    var spd: fx = 1.8fx;               // etSpeedD(0, 1.2,1.8,3.2,4.2, 1,1,1,1), M=1
    var shots: int = 2;                // diffI($A, 2, 2, 2, 5)
    if global(GVAR_RANK) == RANK_EASY { spd = 1.2fx; }
    if global(GVAR_RANK) == RANK_HARD { ways = 3; spd = 3.2fx; }
    if global(GVAR_RANK) >= RANK_LUNATIC { ways = 3; spd = 4.2fx; shots = 5; }
    sh_reset(0);
    sh_sprite(0, TH16_RING_BALL, BULLET_COLOR);   // etSprite(0, 6, 6)
    sh_ring(0, 0);
    sh_aim(0, 1);                      // etAim(0, 0)
    sh_angle(0, 0deg, 3deg);           // etAngle(0, 0.0f, 0.05235988f)
    sh_count(0, ways, 1);
    sh_speed(0, spd, 0fx);
    for i in 0..shots {
        sh_fire(0);                    // etOn(0)
        wait(20);                      // all difficulties wait 20
    }
}

// ---------------------------------------------------------------------------
// MainSub01:1143-1161 (8 GirlB01, 60-frame schedule)
// ---------------------------------------------------------------------------
sub main_sub01() {
    _ = spawn_enemy(128fx, -24fx, 400, 0, 0, 0, girl_b);
    _ = spawn_enemy(-128fx, -24fx, 400, 0, 0, 0, girl_b);
    wait(60);
    _ = spawn_enemy(48fx, -24fx, 400, 0, 0, 0, girl_b);
    wait(60);
    _ = spawn_enemy(-64fx, -24fx, 400, 0, 0, 0, girl_b);
    wait(60);
    _ = spawn_enemy(160fx, -24fx, 400, 0, 0, 0, girl_b);
    wait(60);
    _ = spawn_enemy(-32fx, -24fx, 400, 0, 0, 0, girl_b);
    wait(60);
    _ = spawn_enemy(-190fx, -24fx, 400, 0, 0, 0, girl_b);
    wait(60);
    _ = spawn_enemy(0fx, -24fx, 400, 0, 0, 0, girl_b);
    wait(60);
}

// ---------------------------------------------------------------------------
// MainSub01b:1163-1184 (13 GirlBlueA01 then 7 GirlRedA01, 15-frame schedule)
// ---------------------------------------------------------------------------
async sub main_sub01b() {
    var a: int = -120;
    for i in 0..13 {                   // $B = 13, if ($B--) goto create
        _ = spawn_enemy(a as fx, -20fx, 60, 0, 0, 0, girl_a);
        a = a + 20;
        wait(15);
    }
    for j in 0..7 {                    // $C = 7, if ($C--) goto create
        _ = spawn_enemy((a + 60) as fx, -8fx, 60, 0, 0, 0, girl_a);
        a = a - 40;
        wait(15);
    }
}

// ---------------------------------------------------------------------------
// Shell
// ---------------------------------------------------------------------------
async sub pattern() {
    wait(OPENING_BUFFER);
    spawn main_sub01b();   // source async branch starts with the sync one
    main_sub01();          // source @MainSub01() sync
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
